#!/usr/bin/env sh
# Installs the Kibana data views, one advanced setting, then imports the Sentinel dashboard
# (2 data views + 12 visualizations + 1 dashboard, generated by scripts/build_kibana_objects.py).
# The logs data view is mandatory (fails the container); the dashboard import is reported loudly but does not
# block the stack, and scripts/verify_s3.py fails if the objects are missing.
set -eu

KIBANA_URL="${KIBANA_URL:-http://kibana:5601}"
DATA_VIEW_FILE="${DATA_VIEW_FILE:-/setup/kibana-data-view.json}"
ALERTS_DATA_VIEW_FILE="${ALERTS_DATA_VIEW_FILE:-/setup/kibana-data-view-alerts.json}"
OBJECTS_FILE="${OBJECTS_FILE:-/setup/sentinel-dashboard.ndjson}"

curl -fsS -X POST "${KIBANA_URL}/api/data_views/data_view" \
  -H 'kbn-xsrf: campusguard-setup' \
  -H 'Content-Type: application/json' \
  --data-binary "@${DATA_VIEW_FILE}"
printf '\nKibana data view installed.\n'

if [ -f "${ALERTS_DATA_VIEW_FILE}" ]; then
  curl -sS -X POST "${KIBANA_URL}/api/data_views/data_view" \
    -H 'kbn-xsrf: campusguard-setup' -H 'Content-Type: application/json' \
    --data-binary "@${ALERTS_DATA_VIEW_FILE}" || printf 'WARNING: alerts data view not installed.\n'
  printf '\n'
fi

# The dashboard mixes two data views (logs and alerts): a filter on a logs-only field (e.g. service.name)
# must not empty the alert panels.
curl -sS -X POST "${KIBANA_URL}/api/kibana/settings" \
  -H 'kbn-xsrf: campusguard-setup' -H 'Content-Type: application/json' \
  --data-binary '{"changes":{"courier:ignoreFilterIfFieldNotInIndex":true}}' >/dev/null \
  && printf 'Kibana setting courier:ignoreFilterIfFieldNotInIndex=true\n' || printf 'WARNING: Kibana setting not applied.\n'

if [ -f "${OBJECTS_FILE}" ]; then
  RESULT="$(curl -sS -X POST "${KIBANA_URL}/api/saved_objects/_import?overwrite=true" \
    -H 'kbn-xsrf: campusguard-setup' -F "file=@${OBJECTS_FILE}" || true)"
  printf '%s\n' "${RESULT}"
  case "${RESULT}" in
    *'"success":true'*) printf 'Kibana dashboard imported.\n' ;;
    *) printf 'WARNING: KIBANA IMPORT FAILED - run scripts/verify_s3.py and check the message above.\n' ;;
  esac
fi
